import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.4s5LDCII.js";const n=JSON.parse('{"title":"成人慢性肾脏病食养指南（2024年版）","description":"国家卫健委《成人慢性肾脏病食养指南（2024年版）》可执行整理：按分期实施的低蛋白膳食行动清单，每条出处可一键跳回原文对应页。","frontmatter":{"title":"成人慢性肾脏病食养指南（2024年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2024年版","published":"2024-02","source_url":"https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369/files/1732845128797_75692.pdf","status":"现行","tags":["慢性肾脏病","食养","低蛋白饮食","行动清单"],"reviewed":false,"description":"国家卫健委《成人慢性肾脏病食养指南（2024年版）》可执行整理：按分期实施的低蛋白膳食行动清单，每条出处可一键跳回原文对应页。"},"headers":[],"relativePath":"guides/ckd-2024.md","filePath":"guides/ckd-2024.md"}'),g={name:"guides/ckd-2024.md"};function h(i,t,s,o,l,f){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="成人慢性肾脏病食养指南-2024年版" tabindex="-1">成人慢性肾脏病食养指南（2024年版） <a class="header-anchor" href="#成人慢性肾脏病食养指南-2024年版" aria-label="Permalink to &quot;成人慢性肾脏病食养指南（2024年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据官方 PDF 原文整理，尚未逐条对照原文校验；校验通过前请以原文为准。<strong>肾病膳食与分期强相关，执行前务必经医生或临床营养师确认分期与方案。</strong></p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页所有建议均<strong>整理自官方文件原文</strong>，每条&quot;出处&quot;均可点击直达原文对应页；标注【本站提示】的少数条目为中性工具提示，不代表医学建议。本站不构成诊疗建议，与医生的治疗方案冲突时，<strong>以医嘱为准</strong>。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369/files/1732845128797_75692.pdf" target="_blank" rel="noreferrer">官方全文 PDF（卫健委直链）</a>）· 一级来源。下文&quot;出处&quot;链接指向本站镜像的<a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf" target="_blank" rel="noreferrer">官方原文 PDF</a>（政府公文，属公共领域）。</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>成人慢性肾脏病患者及其照护者，面向不同分期（1～2 期、3～5 期、透析阶段）给出差异化建议；基层卫生工作者与营养指导人员亦可参考（<a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=3" target="_blank" rel="noreferrer">原文·前言</a>）。</p><h2 id="速览卡-一屏看完" tabindex="-1">速览卡（一屏看完） <a class="header-anchor" href="#速览卡-一屏看完" aria-label="Permalink to &quot;速览卡（一屏看完）&quot;">​</a></h2><p><strong>十条原则</strong>：食物多样分期选配 → 能量充足体重合理 → 蛋白适量 → 蔬菜充足水果适量 → 少盐控油限磷控钾 → 适量饮水量出为入 → 食药物质调补有道 → 合理选择营养健康食品 → 规律进餐限酒适度运动 → 定期监测强化自我管理。（<a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=6" target="_blank" rel="noreferrer">原文·三</a>）</p><table tabindex="0"><thead><tr><th>关键数字</th><th>数值</th><th>出处</th></tr></thead><tbody><tr><td>食物品种</td><td>每天 <strong>≥12 种</strong>、每周 <strong>≥25 种</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=7" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>低蛋白饮食（3～5 期）</td><td>蛋白质 <strong>0.6g/kg 理想体重/日</strong>（理想体重=身高cm−105）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>能量</td><td><strong>30～35kcal/kg 理想体重/日</strong>；超重肥胖者可减 500～750kcal</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>BMI</td><td><strong>18.5～23.9</strong>（65 岁以上 20.0～26.9）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>主食</td><td>1～2 期 1/3 为粗杂粮；3～5 期用低蛋白主食（红薯、土豆、山药、粉丝等）替代部分米面</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>优质蛋白</td><td>占蛋白质总量 <strong>50% 以上</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=9" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>红肉</td><td><strong>每周 1～2 次、每次 ≤50g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=9" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>鸡蛋 / 奶</td><td>鸡蛋 <strong>≤1 个/日</strong>；奶 <strong>≤300mL/日</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=9" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>蔬菜 / 水果</td><td><strong>300～500g / 200～350g</strong>（糖尿病肾病水果 100～200g）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=10" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>食盐</td><td><strong>≤5g</strong>；水肿者 ≤3g；严重水肿无盐膳食（钠&lt;1000mg）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=11" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>烹调油</td><td><strong>25～40g</strong>，脂肪供能 ≤35%</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=11" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>磷</td><td><strong>800～1000mg/日</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=11" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>饮水</td><td>无水肿且尿量正常 <strong>1500～1700mL</strong>；水肿/少尿者量出为入</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=12" target="_blank" rel="noreferrer">三(六)</a></td></tr></tbody></table><h2 id="行动清单" tabindex="-1">行动清单 <a class="header-anchor" href="#行动清单" aria-label="Permalink to &quot;行动清单&quot;">​</a></h2><h3 id="🛒-买" tabindex="-1">🛒 买 <a class="header-anchor" href="#🛒-买" aria-label="Permalink to &quot;🛒 买&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>植物性食物为主；3～5 期买低蛋白高能量主食（红薯、土豆、山药、藕、绿豆粉丝、小麦淀粉等）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=8" target="_blank" rel="noreferrer">三(一)(二)</a></td></tr><tr><td>蛋白来源优先鱼禽类，其次大豆类，最后蛋奶畜肉</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=9" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>不买烟熏、烧烤、腌制等过度加工食品</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=7" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>买加工食品看标签，避免含<strong>磷添加剂</strong>多的食品</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=11" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>【本站提示】&quot;磷添加剂&quot;常以磷酸盐字样出现在配料表（如磷酸二氢钠），见到要多留意</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=11" target="_blank" rel="noreferrer">三(五)</a></td></tr></tbody></table><h3 id="🍳-做" tabindex="-1">🍳 做 <a class="header-anchor" href="#🍳-做" aria-label="Permalink to &quot;🍳 做&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>少盐、少调味品；限酒或不饮酒；<strong>限制或禁食浓肉汤、老火汤</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=7" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>用天然味道替代盐：山楂、柠檬、辣椒、花椒、醋</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=11" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>高钾血症者：蔬菜清水浸泡并<strong>飞水弃汤</strong>后进食</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=10" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>3～5 期可适当增加亚麻籽油、紫苏籽油等富含 ω-3 的油脂作能量补充</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=11" target="_blank" rel="noreferrer">三(五)</a></td></tr></tbody></table><h3 id="🍚-吃" tabindex="-1">🍚 吃 <a class="header-anchor" href="#🍚-吃" aria-label="Permalink to &quot;🍚 吃&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么吃</th><th>出处</th></tr></thead><tbody><tr><td>1～2 期：植物性食物为主，餐餐有蔬菜，常吃奶类大豆，适量鱼禽蛋畜肉</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>3～5 期：低蛋白饮食（0.6g/kg 理想体重），兼顾优质蛋白</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>5 期透析阶段仍以植物性食物为主，依情况调整动物性食物、豆类、蔬果</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>蛋、奶含磷较高，适当控制用量</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=9" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>3～5 期多选蛋白质少的瓜菜，适当选深色蔬果</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=10" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>高钾血症者严格控高钾食物，每日钾 ≤2000～3000mg，避免浓肉汤、老火汤、菜汤</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=11" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>按证型选食药物质：脾气虚山药茯苓、肾气虚黄精山药、血虚阿胶、湿热赤小豆金银花菊花、血瘀桃仁山楂</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=12" target="_blank" rel="noreferrer">三(七)</a></td></tr><tr><td>因时制宜：春大枣龙眼核桃仁；夏赤小豆冬瓜绿豆薏苡仁；秋雪梨山药蜂蜜银耳；冬当归（作香辛料）、阿胶</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=12" target="_blank" rel="noreferrer">三(七)</a></td></tr></tbody></table><h3 id="🏃-动-🩺-测与就医" tabindex="-1">🏃 动 / 🩺 测与就医 <a class="header-anchor" href="#🏃-动-🩺-测与就医" aria-label="Permalink to &quot;🏃 动 / 🩺 测与就医&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>规律进餐定时定量，避免过度饥饿或暴饮暴食；适度运动</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=14" target="_blank" rel="noreferrer">三(九)</a></td></tr><tr><td>定期营养评定与监测；发现营养风险及时膳食指导</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=13" target="_blank" rel="noreferrer">三(八)</a>、<a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=15" target="_blank" rel="noreferrer">三(十)</a></td></tr><tr><td>必要时在临床营养师/医生指导下使用膳食营养补充剂、肾病型能量补充剂、特殊医学用途配方食品</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=13" target="_blank" rel="noreferrer">三(八)</a></td></tr><tr><td>合并水肿患者的低盐膳食方案，须在专科医生指导下实施</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=11" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>出现高钾血症及时就医</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=11" target="_blank" rel="noreferrer">三(五)</a></td></tr></tbody></table><h2 id="常见误区-原文明确告诫" tabindex="-1">常见误区（原文明确告诫） <a class="header-anchor" href="#常见误区-原文明确告诫" aria-label="Permalink to &quot;常见误区（原文明确告诫）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>原文怎么说</th><th>出处</th></tr></thead><tbody><tr><td>&quot;肾病就要极低蛋白&quot;</td><td>低蛋白饮食不当易致营养不足；优质蛋白应占 50% 以上，须按分期定量</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=9" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>&quot;喝汤养肾&quot;</td><td>限制或禁食浓肉汤、老火汤；高钾者避免各类菜汤肉汤</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=7" target="_blank" rel="noreferrer">三(一)</a>、<a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=11" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>&quot;牛奶鸡蛋多多益善&quot;</td><td>蛋类和奶类含磷较高，鸡蛋每天 ≤1 个、奶 ≤300mL</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=9" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>&quot;植物蛋白不如动物蛋白&quot;</td><td>植物性食物更有利于减轻肾脏负担；大豆制品是蛋白和钙的重要来源</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=9" target="_blank" rel="noreferrer">三(三)</a></td></tr></tbody></table><h2 id="附录怎么用" tabindex="-1">附录怎么用 <a class="header-anchor" href="#附录怎么用" aria-label="Permalink to &quot;附录怎么用&quot;">​</a></h2><ul><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=17" target="_blank" rel="noreferrer">附录1《食物选择》</a></strong>：分期的食物选择与推荐量；**<a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=21" target="_blank" rel="noreferrer">附录1·二</a>**证型食药物质举例。</li><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=22" target="_blank" rel="noreferrer">附录2《常见食物交换表》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=28" target="_blank" rel="noreferrer">附录3《不同地区食谱示例》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=65" target="_blank" rel="noreferrer">附录4《食养方举例》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/ckd-2024.pdf#page=68" target="_blank" rel="noreferrer">附录5《诊断、分期营养管理原则》</a></strong>。</li></ul><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2024 年版（现行）</td></tr><tr><td>印发时间</td><td>2024 年 2 月</td></tr><tr><td>原文直链</td><td><a href="https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369/files/1732845128797_75692.pdf" target="_blank" rel="noreferrer">卫健委官网 PDF</a></td></tr></tbody></table>',24)])])}const u=e(g,[["render",h]]);export{n as __pageData,u as default};
